1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.web.HttpHeaderParameter;
5	
6	/**
7	 * Entry step of the create pipeline, routing to exactly one of two outputs. When the request carries
8	 * an {@code Idempotency-Key} that has already created an owner (see {@link IdempotencyStore}), it
9	 * takes the {@code existing} output to replay that owner with 200, short-circuiting the create so the
10	 * request never reaches the duplicate checks (which would otherwise reject the repeat with 409). With
11	 * no key, or a key not seen before, it takes the {@code proceed} output and the normal create runs;
12	 * {@link RecordIdempotencyKey} then registers the key once the owner is saved.
13	 */
14	public class CheckIdempotency {
15	
16	    /** Branch taken for a repeated key: replays the owner the key first created, by its id. */
17	    @FunctionalInterface
18	    public interface ExistingOwnerFlow {
19	        void replay(Integer ownerId);
20	    }
21	
22	    /** Branch taken for a new (or absent) key: runs the normal create pipeline. */
23	    @FunctionalInterface
24	    public interface ProceedFlow {
25	        void proceed();
26	    }
27	
28	    public void service(
29	            @HttpHeaderParameter("Idempotency-Key") String idempotencyKey,
30	            IdempotencyStore idempotencyStore, @Flow("existing") ExistingOwnerFlow existing,
31	            @Flow("proceed") ProceedFlow proceed) {
32	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
33	            Integer existingId = idempotencyStore.lookup(idempotencyKey).orElse(null);
34	            if (existingId != null) {
35	                existing.replay(existingId);
36	                return;
37	            }
38	        }
39	        proceed.proceed();
40	    }
41	}
