1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingRequiredFieldsException;
9	
10	/**
11	 * Rejects a create request that is missing or blank in any required owner field, reporting every
12	 * offending field at once. Reads the request <em>without</em> {@code @Valid} so this rule decides the
13	 * 400 response shape rather than bean validation. Runs after {@link NormalizeAddress}, so the address
14	 * is judged in its normalized form and a value that is blank after normalization is rejected.
15	 */
16	public class ValidateOwnerFields {
17	
18	    public void service(@Val OwnerFieldsDto request)
19	            throws MissingRequiredFieldsException {
20	        List<String> missing = new ArrayList<>();
21	        requirePresent(missing, "firstName", request.getFirstName());
22	        requirePresent(missing, "lastName", request.getLastName());
23	        requirePresent(missing, "address", request.getAddress());
24	        requirePresent(missing, "city", request.getCity());
25	        requirePresent(missing, "telephone", request.getTelephone());
26	        if (!missing.isEmpty()) {
27	            throw new MissingRequiredFieldsException(missing);
28	        }
29	    }
30	
31	    private static void requirePresent(List<String> missing, String field, String value) {
32	        if (value == null || value.isBlank()) {
33	            missing.add(field);
34	        }
35	    }
36	}
