9	/**
10	 * Validates a supplied registrationDate <em>only when present</em>: it may not be later than the
11	 * server's current date. A missing date is allowed and later defaults to the server date (see
12	 * {@link ResolveRegistrationDate}). Judges the raw supplied date, before it is rolled onto a
13	 * business day, so the check reflects exactly what the request asked for. A future date is a 400 via
14	 * {@link FutureRegistrationDateException}.
15	 */
16	public class ValidateRegistrationDate {
17	
18	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
19	        LocalDate registrationDate = request.getRegistrationDate();
20	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
21	            throw new FutureRegistrationDateException(registrationDate);
22	        }
23	    }
24	}
