1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
8	import org.springframework.samples.petclinic.util.CityRegion;
9	import org.springframework.samples.petclinic.util.RegionPostcodes;
10	
11	/**
12	 * Validates an owner's postcode <em>only when present</em>: a supplied postcode must be four digits
13	 * and fall within the range its city's region permits (see {@link RegionPostcodes}), with a city of
14	 * no known region ({@link CityRegion}) accepting any 4-digit code. A missing or blank postcode is
15	 * allowed, keeping the create/update contract backward-compatible. An offending postcode is a 400 via
16	 * {@link InvalidPostcodeException}.
17	 */
18	public class ValidatePostcode {
19	
20	    private static final Pattern FOUR_DIGITS = Pattern.compile("\\d{4}");
21	
22	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
23	        String postcode = request.getPostcode();
24	        if (postcode == null || postcode.isBlank()) {
25	            return;
26	        }
27	        if (!FOUR_DIGITS.matcher(postcode).matches()
28	                || !RegionPostcodes.allows(CityRegion.of(request.getCity()), Integer.parseInt(postcode))) {
29	            throw new InvalidPostcodeException(postcode, request.getCity());
30	        }
31	    }
32	}
