5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
7	
8	/**
9	 * Rejects a create request whose city has already reached capacity: a city is full once it holds
10	 * {@link #CAPACITY} or more existing owners, compared case-insensitively. A full city is a 409 via
11	 * {@link CityAtCapacityException}.
12	 */
13	public class EnsureCityCapacity {
14	
15	    /** Maximum number of owners a single city may hold. */
16	    static final int CAPACITY = 50;
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws CityAtCapacityException {
20	        String city = request.getCity();
21	        if (ownerRepository.countInCity(city) >= CAPACITY) {
22	            throw new CityAtCapacityException(city, CAPACITY);
23	        }
24	    }
25	}
