1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
6	
7	/**
8	 * Normalizes the optional email of a create request: an absent or blank email is left untouched, while
9	 * a present one must be a syntactically valid address. The lower-cased form is written back onto the
10	 * (republished) request so {@link BuildOwner} stores and later responses return it lower-cased. An
11	 * invalid value is rejected as a 400 via {@link InvalidEmailException}.
12	 */
13	public class NormalizeEmail {
14	
15	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
16	        String email = request.getEmail();
17	        if (email == null || email.isBlank()) {
18	            return;
19	        }
20	        String normalized = EmailNormalizer.normalize(email);
21	        if (!EmailNormalizer.isValid(normalized)) {
22	            throw new InvalidEmailException(email);
23	        }
24	        request.setEmail(normalized);
25	    }
26	}
