1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.util.BusinessDay;
8	
9	/**
10	 * Resolves an owner's effective registration date and rolls it onto a business day. The effective
11	 * date is the one supplied on the create request, or the server's current date when the request
12	 * omits it. Either way, a Saturday, Sunday or public holiday rolls forward to the next non-holiday
13	 * business day (see {@link BusinessDay#onOrAfter(LocalDate)}). Runs before the customer code,
14	 * membership number and daily create-limit are derived, so all of them key off the adjusted date.
15	 * Mutates the built {@link Owner} in place.
16	 */
17	public class ResolveRegistrationDate {
18	
19	    public void service(@Val Owner owner) {
20	        LocalDate effective = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
21	        owner.setRegistrationDate(BusinessDay.onOrAfter(effective));
22	    }
23	}
