3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Flags a create request whose city is approaching capacity: the owner's capacity warning is set
9	 * when the city already holds between {@link #WARNING_THRESHOLD} and {@link EnsureCityCapacity#CAPACITY}
10	 * (exclusive) existing owners, compared case-insensitively — the same count {@link EnsureCityCapacity}
11	 * uses to enforce the hard limit. Runs after {@link BuildOwner} so it keys off the built owner's city,
12	 * and before {@link SaveOwner} so the count excludes the owner currently being created. Mutates the
13	 * built {@link Owner} in place.
14	 */
15	public class FlagCapacityWarning {
16	
17	    /** A city warns once it already holds at least this many owners (up to, but not at, capacity). */
18	    static final int WARNING_THRESHOLD = 40;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        long existing = ownerRepository.countInCity(owner.getCity());
22	        owner.setCapacityWarning(existing >= WARNING_THRESHOLD && existing < EnsureCityCapacity.CAPACITY);
23	    }
24	}
