1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.util.IdentityVersion;
6	import org.springframework.samples.petclinic.util.Locality;
7	import org.springframework.samples.petclinic.util.MemberId;
8	
9	/**
10	 * Assigns the owner's memberId, formatted {@code <REGION><FY><HASH8><CHK>} (see {@link MemberId}):
11	 * REGION is the {@link IdentityVersion#regionCode(String) version-2 region code} — the region derived
12	 * from the owner's postcode (falling back to the city; see {@link Locality}) with the version tag
13	 * mixed in — FY the two-digit fiscal year of the resolved registration date, HASH8 the first eight
14	 * upper-case hex characters of SHA-256 over the normalized telephone and last name, and CHK the Luhn
15	 * check digit over the {@code <REGION><FY><HASH8>} body. The owner's telephone is already in canonical
16	 * E.164 form here, having been normalized upstream by {@link NormalizeTelephone}, and its registration
17	 * date has been resolved by {@link ResolveRegistrationDate}. The identity carries no per-owner
18	 * sequence, so it does not depend on other owners. Mutates the built {@link Owner} in place.
19	 */
20	public class AssignMemberId {
21	
22	    public void service(@Val Owner owner) {
23	        String region = IdentityVersion.regionCode(Locality.of(owner.getCity(), owner.getPostcode()));
24	        owner.setMemberId(
25	                MemberId.of(region, owner.getRegistrationDate(), owner.getTelephone(), owner.getLastName()));
26	    }
27	}
