1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.util.MemberId;
10	
11	/**
12	 * Guarantees the assigned memberId is unique across owners. When the id computed by
13	 * {@link AssignMemberId} already belongs to an existing owner, it appends {@code -<n>} with the
14	 * smallest {@code n} of 2 or more that makes it unique (see {@link MemberId#dedupe}). Runs before
15	 * {@link SaveOwner}, so the owner being created is not yet persisted and cannot collide with itself.
16	 * Mutates the built {@link Owner} in place.
17	 */
18	public class DeduplicateMemberId {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        Set<String> existing = new HashSet<>();
22	        for (Owner other : ownerRepository.findAll()) {
23	            if (other.getMemberId() != null) {
24	                existing.add(other.getMemberId());
25	            }
26	        }
27	        owner.setMemberId(MemberId.dedupe(owner.getMemberId(), existing));
28	    }
