23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (HouseholdNormalizer.belongsTo(existing, householdId)) {
25	                Integer level = MembershipLevel.forPoints(MembershipPoints.of(existing));
26	                if (level != null && (maxLevel == null || level > maxLevel)) {
27	                    maxLevel = level;
28	                }
29	            }
30	        }
31	        owner.setMembershipLevelCap(maxLevel == null ? null : maxLevel + 1);
32	    }
